import { PGlite } from "@electric-sql/pglite";

const migrations = [
  { id: 1, sql: "create table tasks (id integer primary key)" },
  { id: 2, sql: "alter table tasks add column title text" },
];

async function migrate(db) {
  await db.exec("create table if not exists schema_migrations (id integer primary key)");
  const done = new Set((await db.query("select id from schema_migrations")).rows.map((r) => r.id));
  const applied = [];
  for (const m of migrations) {
    if (done.has(m.id)) continue;
    await db.transaction(async (tx) => {
      await tx.exec(m.sql);
      await tx.query("insert into schema_migrations (id) values ($1)", [m.id]);
    });
    applied.push(m.id);
  }
  return applied;
}

const db = new PGlite();
console.log(await migrate(db), await migrate(db));
await db.close();

