const migrations = [
  { id: 3, name: "add due date" },
  { id: 1, name: "create tasks" },
  { id: 4, name: "index due date" },
  { id: 2, name: "add done" },
];

function pending(migrations, appliedIds) {
  const done = new Set(appliedIds);
  return migrations
    .filter((m) => !done.has(m.id))
    .toSorted((a, b) => a.id - b.id)
    .map((m) => m.name);
}

console.log(pending(migrations, [1, 2]));
console.log(pending(migrations, [1, 2, 3, 4]));

