function checkTask(task) {
  const broken = [];
  const length = task.title.trim().length;
  if (length < 1 || length > 100) broken.push("title");
  if (!Number.isInteger(task.priority) || task.priority < 1 || task.priority > 3) broken.push("priority");
  return broken;
}

