const tasks = [
  { id: 1, userId: 7 },
  { id: 2, userId: 9 },
  { id: 3, userId: 7 },
  { id: 4, userId: 8 },
];

function buildIndex(rows, column) {
  const index = new Map();
  for (const row of rows) {
    const key = row[column];
    if (!index.has(key)) index.set(key, []);
    index.get(key).push(row.id);
  }
  return index;
}

const byUser = buildIndex(tasks, "userId");
console.log(byUser.get(7), byUser.get(8), byUser.get(42));
